package com.portfolio.features.asset.controller; import com.portfolio.features.asset.config.StorageProperties; import java.nio.file.*; import lombok.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/public/assets") @ConditionalOnProperty(name="app.storage.type",havingValue="local",matchIfMissing=true) @RequiredArgsConstructor public class PublicAssetController {private final StorageProperties props;@GetMapping("/**") public ResponseEntity<Resource> get(jakarta.servlet.http.HttpServletRequest r)throws Exception{String p=r.getRequestURI().substring("/api/public/assets/".length());Path root=Paths.get(props.getLocalPath()).toAbsolutePath().normalize(),file=root.resolve(p).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))return ResponseEntity.notFound().build();String type=Files.probeContentType(file);return ResponseEntity.ok().contentType(type==null?MediaType.APPLICATION_OCTET_STREAM:MediaType.parseMediaType(type)).contentLength(Files.size(file)).body(new FileSystemResource(file));}}
